import traceback

def failing_first_completed(record):
    return record['completed'][0]

small_repro = {'completed': []}
try:
    failing_first_completed(small_repro)
except IndexError as error:
    frames = traceback.extract_tb(error.__traceback__)
    print(type(error).__name__)
    print(frames[-1].name)

def first_completed(record):
    completed = record['completed']
    if not completed:
        return None
    return completed[0]

print(first_completed(small_repro))
print(first_completed({'completed': ['loops']}))
